def reference(vectors):
    def get_int(row, key, default=0, mask=None):
        v = row.get(key, default)
        if isinstance(v, str):
            try:
                v = int(v, 0)
            except:
                v = int(v)
        else:
            v = int(v)
        if mask is not None:
            v &= mask
        return v

